package com.google.gson;import java.util.regex.*;public class Gson {public <T> T fromJson(String text,Class<T> type){if(text==null||!text.trim().startsWith("{"))throw new IllegalArgumentException("malformed");JsonObject root=new JsonObject(),data=new JsonObject();Matcher m=Pattern.compile("\\\"([^\\\"]+)\\\"\\s*:\\s*(?:\\\"([^\\\"]*)\\\"|(\\d+|true|false))").matcher(text);while(m.find()){String key=m.group(1),v=m.group(2)!=null?m.group(2):m.group(3);if(key.equals("translatedText"))data.add(key,new JsonElement(v));else root.add(key,new JsonElement(v));}root.add("responseData",data);return (T)root;}}
